def solve(g):
    n,h=len(g),len(g[0])
    # varied line: find line whose cells are not all equal and span h distinct values
    for side,cnt in [('row',n),('col',h)]:
        if side=='row':
            for r in range(n):
                vals=set(g[r])
                if len(vals)==cnt:
                    s=sorted(g[r]); idx=r
                    break
        else:
            for cc in range(h):
                if len(set(g[r][cc] for r in range(n)))==cnt:
                    idx=cc; break
    if side=='row':
        out=[list(g[r]) for r in range(n)]
        # fill rows from idx+1 downward; s order top->bottom
        d=0
        for r in range(idx+1,n):
            for c in range(h):
                out[r][c]=s[len(s)-1-d%(len(s))] if d==0 else s[(d-1)%len(s)]
                d+=1
        return out
    else:
        out=[list(row) for row in g]
        for r in range(n):
            for c in range(idx-1,-1,-1):
                d=idx-1-c
                out[r][c]=s[(d-1)%len(s)]
        return out
