# Hypothesis: find the line whose values are all distinct -> the "key" line.
# All other cells get filled cyclically with that line's values, starting adjacent to the key line,
# cycling through the full sequence (ending with last value), repeating until filling whole grid.
def solve(g):
    n=len(g); h=len(g[0])
    # find varied line
    var=None
    for i in range(h):
        if len(set(g[r][i] for r in range(n)))==n:
            var=(i,'col',[g[r][i] for r in range(n)])
            break
    if var is None:
        for j in range(n):
            if len(set(g[j][i] for i in range(h)))==h:
                var=(j,'row',[g[i][j] for i in range(n)])
                break
    assert var
    idx,side,vals=var
    L=len(vals)
    out=[list(row) for row in g]
    if side=='col':
        for r in range(n):
            for c in range(h):
                if c!=idx:
                    # distance from edge: number of steps away from key line
                    d=abs(idx-c)
                    # sequence starts at vals[L-1] (last value) then cycles forward
                    out[r][c]=vals[(L-1+d)%L]
    else:
        for c in range(h):
            for r in range(n):
                if r!=idx:
                    d=abs(idx-r)
                    out[r][c]=vals[(L-1+d)%L]
    return out

