# Hypothesis: fill starts adjacent to the key line with s[-1] and cycles in the direction
# determined by... try: for vertical keys cycle BACKWARD, for horizontal cycle FORWARD,
# anchored at s[-1] adjacent. Verify against BOTH demos exactly.
def solve(g):
    n,h=len(g),len(g[0])
    # find varied line
    var=None
    for i in range(h):
        if len(set(g[r][i] for r in range(n)))==n:
            var=(i,'col',[g[r][i] for r in range(n)])
            break
    else:
        for j in range(n):
            if len(set(g[j][i] for i in range(h)))==h:
                var=(j,'row',[g[i][j] for i in range(n)])
                break
    assert var
    idx,side,vals=var; L=len(vals)
    out=[list(row) for row in g]
    for _ in range(idx,n)*4 if side=='col' else range(h): pass
    # fill away from key line: uniform cells only
    for r in range(n):
        for c in range(h):
            if g[r][c]==out[0][0]: continue
            d=abs(c-idx) if side=='col' else abs(r-idx)
            # anchor: adjacent cell gets vals[-1]; then cycle in direction opposite for vertical, same for horizontal
            if side=='col':
                # backward cycle: vals[-1],vals[-2],...
                out[r][c]=vals[(L-1-d)%L]
            else:
                out[r][c]=vals[(d-1+len(vals))%L] if d>0 else vals[0]
    return out

